"use strict";
// Value origin for the Eclipse plugin: the VS Code analysis and its page, as one script for the plugin's browser.
// The modules are the VS Code files unchanged, found by following the requires of value-origin-entry.js with the
// bundler the analysis worker is built with (frontend-bundle.js). A module that needs Node fails when it is built,
// or says so when it is used - never by being left out of a list.
const path = require("node:path");
const { build } = require("./frontend-bundle");

// abaplint comes as a script of its own (assistant/abaplint.js, window.vertexAbaplint), put in before this one:
// call-graph asks it which calls are built-in functions, and value-origin-linter parses with it.
const ABAPLINT = "function () { if (!window.vertexAbaplint) { throw new Error('abaplint did not load into this window.'); } return window.vertexAbaplint; }()";

function bundle(root = path.join(__dirname, "..")) {
  return "// Generated by eclipse/prepare.js from eclipse/value-origin-entry.js and the vscode/ modules it requires - edit those.\n"
    + build(root, [["vertexOrigin", "eclipse/value-origin-entry.js"]], { externals: { "@abaplint/core": ABAPLINT } }) + "\n";
}

module.exports = { bundle };
